// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {W_WALLET, Log} from "../src/W_WALLET.sol";

contract InvMutTest is Test {
    W_WALLET c;
    function setUp() public { c = new W_WALLET(address(new Log())); }

    function testFuzz_property(uint256 v1, uint256 v2, address actor) public {
        vm.assume(actor != address(0) && actor != address(c));
        v1 = bound(v1, 1, 1 ether);
        v2 = bound(v2, 1, 1 ether);

        vm.deal(actor, v1 + v2);
        vm.prank(actor);
        c.Put{value: v1}(0);

        // second deposit arrives through the fallback path (empty calldata)
        vm.prank(address(this));
        (bool sent, ) = actor.call("");
        sent; // silence unused
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: v2}("");
        assertTrue(ok);

        uint256 bal;
        (, bal) = c.Acc(actor);
        assertTrue(bal == v1 + v2);
    }
}
